// Some portions generated by Co-Pilot
"use client";

import React from "react";
import * as Highcharts from "highcharts";
import { Chart } from "@highcharts/react";

if (!Highcharts.AST.allowedAttributes.includes("rel")) {
  Highcharts.AST.allowedAttributes.push("rel");
}

export interface PieChartPoint {
  name: string;
  y: number;
  id?: string;
  visible?: boolean;
}

interface PieChartProps {
  data?: PieChartPoint[];
  name?: string;
  showInLegend?: boolean;
  dataLabels?: boolean;
  colors?: string[] | undefined;
  sourceUrl?: string;
  onPointClick?: (point: { id?: string; name: string }) => void;
}

const DEFAULT_SOURCE_URL = "https://api.adoptium.net/v3/stats/downloads/total";

const PieChart: React.FC<PieChartProps> = ({
  data,
  name,
  showInLegend = false,
  dataLabels = false,
  colors = undefined,
  sourceUrl = DEFAULT_SOURCE_URL,
  onPointClick,
}) => {
  if (!data) return null;
  const sourceLabel = sourceUrl.replace(/^https?:\/\//, "");

  const options = {
    chart: {
      type: "pie",
      backgroundColor: "transparent",
      style: { fontFamily: "inherit" },
      animation: process.env.NODE_ENV !== "test",
    },
    title: {
      text: name,
      style: { color: "#fff", fontWeight: "bold", fontSize: "1.25rem" },
    },
    subtitle: {
      text: `Data is from: <a href="${sourceUrl}" target="_blank" rel="noopener noreferrer">${sourceLabel}</a>`,
      useHTML: true,
      style: { color: "#bdbdbd" },
    },
    accessibility: { enabled: false },
    tooltip: {
      backgroundColor: "#2c225a",
      borderColor: "#6ba4e7",
      style: { color: "#fff", fontWeight: "bold" },
      formatter: function (this: unknown) {
        const ctx = this as {
          y?: number;
          point?: { name: string; percentage: number };
        };
        if (!ctx || !ctx.y) return "";
        const nbDownloads = Highcharts.numberFormat(ctx.y, 0, ".", " ");
        return (
          ctx.point?.name +
          "<b> " +
          ctx.point?.percentage.toFixed(2) +
          "% </b><br/><b> " +
          nbDownloads +
          "</b> downloads"
        );
      },
    },
    plotOptions: {
      pie: {
        allowPointSelect: !onPointClick,
        cursor: "pointer",
        borderColor: "rgba(255,255,255,0.1)",
        borderWidth: 2,
        dataLabels: {
          enabled: dataLabels,
          format: "<b>{point.name}</b>: {point.percentage:.2f} %",
          style: {
            color: "#fff",
            fontWeight: "bold",
            textOutline: "none",
            fontSize: "1rem",
          },
        },
        colors,
        shadow: false,
        showInLegend,
        ...(onPointClick && {
          point: {
            events: {
              click: function (this: Highcharts.Point) {
                onPointClick({
                  id: this.options.custom?.filterKey,
                  name: this.name,
                });
              },
              legendItemClick: function (this: Highcharts.Point) {
                onPointClick({
                  id: this.options.custom?.filterKey,
                  name: this.name,
                });
                return false;
              },
            },
          },
        }),
      },
    },
    legend: {
      itemStyle: { color: "#fff", fontWeight: "bold" },
      itemHoverStyle: { color: "#6ba4e7" },
    },
    series: [
      {
        name,
        colorByPoint: true,
        // Keep filter keys separate from point IDs so reordered slices update by position.
        data: data.map(({ id, ...point }) => ({
          ...point,
          custom: { filterKey: id },
        })),
      },
    ],
  };

  return (
    <div className="chart">
      <Chart options={options} />
    </div>
  );
};

export default PieChart;
